"""In-process pub/sub for live quest log events keyed by JSONL path."""

from __future__ import annotations

import queue
import threading
from pathlib import Path


class ChatSubscription:
    """Receives live log events for one subscribed path."""

    def __init__(
        self,
        *,
        queue: queue.SimpleQueue[dict],
        bus: ChatEventBus,
        key: Path,
    ) -> None:
        self.queue = queue
        self._bus = bus
        self._key = key
        self._unsubscribed = False

    def unsubscribe(self) -> None:
        if self._unsubscribed:
            return
        self._unsubscribed = True
        self._bus._remove_subscriber(self._key, self)


class ChatEventBus:
    """Thread-safe fan-out of quest log events to WebSocket sessions."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._subscribers: dict[Path, list[ChatSubscription]] = {}

    def publish(self, log_path: Path, event: dict) -> None:
        key = log_path.resolve()
        with self._lock:
            subscribers = list(self._subscribers.get(key, ()))
        for subscription in subscribers:
            subscription.queue.put(event)

    def subscribe(self, log_path: Path) -> ChatSubscription:
        key = log_path.resolve()
        subscription = ChatSubscription(
            queue=queue.SimpleQueue(),
            bus=self,
            key=key,
        )
        with self._lock:
            self._subscribers.setdefault(key, []).append(subscription)
        return subscription

    def _remove_subscriber(self, key: Path, subscription: ChatSubscription) -> None:
        with self._lock:
            subscribers = self._subscribers.get(key)
            if not subscribers:
                return
            try:
                subscribers.remove(subscription)
            except ValueError:
                return
            if not subscribers:
                del self._subscribers[key]

"""WebSocket chat stream session: JSONL replay and live event bus."""

from __future__ import annotations

import json
import queue
from pathlib import Path

from .agui_mapper import QuestLogToAguiMapper
from .chat_event_bus import ChatEventBus, ChatSubscription

_BATCH_SIZE = 100
_LIVE_POLL_TIMEOUT = 1.0


class ChatStreamSession:
    """Replays a quest log JSONL file then streams live events from a bus."""

    def __init__(self, log_path: Path, ws, event_bus: ChatEventBus) -> None:
        self._log_path = log_path
        self._ws = ws
        self._event_bus = event_bus

    def run(self) -> None:
        subscription = self._event_bus.subscribe(self._log_path)
        try:
            mapper = QuestLogToAguiMapper()
            replay_high_water = self._replay_file(mapper)
            if replay_high_water is None:
                return
            self._live_loop(mapper, subscription, replay_high_water)
        finally:
            subscription.unsubscribe()

    def _send(self, message: dict) -> bool:
        try:
            self._ws.send(json.dumps(message))
            return True
        except Exception:
            return False

    def _send_events(self, events: list[dict]) -> bool:
        if not events:
            return True
        return self._send({"type": "events", "events": events})

    def _replay_file(self, mapper: QuestLogToAguiMapper) -> int | None:
        replay_high_water = 0
        batch: list[dict] = []

        with self._log_path.open(encoding="utf-8") as fh:
            for raw_line in fh:
                line = raw_line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                except json.JSONDecodeError as exc:
                    if not self._send(
                        {"type": "error", "message": f"invalid JSON: {exc.msg}"}
                    ):
                        return None
                    continue
                if not isinstance(event, dict):
                    if not self._send(
                        {"type": "error", "message": "expected JSON object per line"}
                    ):
                        return None
                    continue

                sequence = event.get("sequence")
                if isinstance(sequence, int):
                    replay_high_water = max(replay_high_water, sequence)

                for agui_event in mapper.consume(event):
                    batch.append(agui_event)
                    if len(batch) >= _BATCH_SIZE:
                        if not self._send_events(batch):
                            return None
                        batch = []

        for agui_event in mapper.flush():
            batch.append(agui_event)
            if len(batch) >= _BATCH_SIZE:
                if not self._send_events(batch):
                    return None
                batch = []

        if batch:
            if not self._send_events(batch):
                return None

        if not self._send({"type": "caught_up"}):
            return None

        return replay_high_water

    def _live_loop(
        self,
        mapper: QuestLogToAguiMapper,
        subscription: ChatSubscription,
        replay_high_water: int,
    ) -> None:
        while True:
            if getattr(self._ws, "closed", False):
                return
            try:
                event = subscription.queue.get(timeout=_LIVE_POLL_TIMEOUT)
            except queue.Empty:
                continue

            sequence = event.get("sequence")
            if isinstance(sequence, int) and sequence <= replay_high_water:
                continue

            agui_events = mapper.consume(event)
            if agui_events and not self._send_events(agui_events):
                return

    }


def resolve_agent_log_path(
    *,
    quest_dir: Path,
    agent_key: str,
    step: int | None,
) -> tuple[int, Path]:
    scope, role = parse_agent_key(agent_key)
    validate_agent_role(scope, role)
    logs = collect_step_logs_for_role(quest_dir, role)
    if not logs:
        raise DashboardNotFound(f"No log artifacts for role {role!r}")

    if step is not None:
        selected = next((p for sn, p in logs if sn == step), None)
        if selected is None:
            raise DashboardNotFound(f"No log for role {role!r} with step={step}")
        return step, selected
    return logs[-1]


def agent_log_payload(
    *,
    quest_dir: Path,
    agent_key: str,
    step: int | None,
) -> dict:
    scope, role = parse_agent_key(agent_key)
    current_step, path = resolve_agent_log_path(
        quest_dir=quest_dir,
        agent_key=agent_key,
        step=step,
    )
    logs = collect_step_logs_for_role(quest_dir, role)

    raw = path.read_text(encoding="utf-8")
    st = path.stat()
    updated = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).strftime(
        "%Y-%m-%dT%H:%M:%SZ"
    )
    try:
        registry = quest_fs.read_thread_registry(quest_dir)
    except (FileNotFoundError, ValueError, json.JSONDecodeError):
        registry = {}
    entry = registry.get(role) if isinstance(registry.get(role), dict) else None
    thread_name = (
        str(entry["thread_name"]) if entry and entry.get("thread_name") else None
    )

    siblings: list[dict] = []
    for step_n, p in sorted(logs, key=lambda t: t[0], reverse=True):
        siblings.append(
            {
                "step": step_n,
                "filename": p.name,
                "relative_path": _relative_under_quest(quest_dir, p),
                "is_current": step_n == current_step,
            }
        )

    return {
        "agent_key": agent_key,
        "scope": scope,
        "role": role,
        "jsonl_raw": raw,
        "metadata": {
            "relative_path": _relative_under_quest(quest_dir, path),
            "step": current_step,
            "filename": path.name,
            "updated_at": updated,
            "thread_name": thread_name,
        },
        "log_siblings": siblings,

"""Tests for ChatEventBus pub/sub."""

from __future__ import annotations

import queue
import threading
import unittest
from pathlib import Path

from quest_runner_service.chat_event_bus import ChatEventBus  # type: ignore[import-not-found]


class ChatEventBusTests(unittest.TestCase):
    def setUp(self) -> None:
        self.bus = ChatEventBus()
        self.log_path = Path("/tmp/quest-runner/test_agent_log.jsonl")

    def _publish(self, event: dict) -> None:
        self.bus.publish(self.log_path, event)

    def test_single_subscriber_receives_event(self) -> None:
        subscription = self.bus.subscribe(self.log_path)
        self.addCleanup(subscription.unsubscribe)

        event = {"sequence": 1, "event_kind": "sheaf.prompt"}
        self._publish(event)

        received = subscription.queue.get(timeout=1.0)
        self.assertIs(received, event)

    def test_multiple_subscribers_receive_same_event(self) -> None:
        first = self.bus.subscribe(self.log_path)
        second = self.bus.subscribe(self.log_path)
        self.addCleanup(first.unsubscribe)
        self.addCleanup(second.unsubscribe)

        event = {"sequence": 2, "event_kind": "sheaf.prompt"}
        self._publish(event)

        self.assertIs(first.queue.get(timeout=1.0), event)
        self.assertIs(second.queue.get(timeout=1.0), event)

    def test_different_path_does_not_receive_event(self) -> None:
        subscription = self.bus.subscribe(Path("/tmp/quest-runner/other_log.jsonl"))
        self.addCleanup(subscription.unsubscribe)

        self._publish({"sequence": 3})

        with self.assertRaises(queue.Empty):
            subscription.queue.get(timeout=0.05)

    def test_unsubscribe_stops_delivery_and_is_idempotent(self) -> None:
        subscription = self.bus.subscribe(self.log_path)

        subscription.unsubscribe()
        subscription.unsubscribe()

        self._publish({"sequence": 4})

        with self.assertRaises(queue.Empty):
            subscription.queue.get(timeout=0.05)

    def test_concurrent_publish_subscribe_smoke(self) -> None:
        errors: list[Exception] = []
        path = self.log_path.resolve()

        def publisher() -> None:
            try:
                for index in range(100):
                    self.bus.publish(path, {"sequence": index})
            except Exception as exc:
                errors.append(exc)

        def subscriber() -> None:
            try:
                for _ in range(10):
                    sub = self.bus.subscribe(path)
                    self.bus.publish(path, {"sequence": 0})
                    sub.unsubscribe()
            except Exception as exc:
                errors.append(exc)

        threads = [
            threading.Thread(target=publisher),
            threading.Thread(target=publisher),
            threading.Thread(target=subscriber),
            threading.Thread(target=subscriber),
        ]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=5.0)
            self.assertFalse(thread.is_alive())

        self.assertEqual(errors, [])


if __name__ == "__main__":
    unittest.main()
